\title{The Sharp Threshold Constant of the Maker--Breaker Cycle Game:\\ A Quantitative Envelope}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
For a fixed cycle length $k \ge 4$, the biased Maker--Breaker $C_k$-game on the
edges of the complete graph $K_n$ exhibits a sharp threshold bias of the form
$q_k(n) = c_k \cdot n^{(k-2)/(k-1)}$, where the sharp constant is
$c_k = \big[(k-1)(2(k-1)/k)^{k-2}\big]^{1/(k-1)}$. We establish the quantitative
envelope of this constant and the monotone behaviour of the resulting bias:
(i) the average-degree factor $2(k-1)/k$ lies in $[3/2,2)$ and is strictly
increasing; (ii) $3/2 \le c_k < 3$ for every $k \ge 4$, so $c_k$ is a genuine
bounded universal constant; (iii) the exponent $(k-2)/(k-1)$ lies strictly in
$(0,1)$ and equals the reciprocal of the maximum $2$-density
$m_2(C_k) = (k-1)/(k-2)$; (iv) the bias is strictly increasing in $n$ and the
sharp-threshold window is nonempty. Two natural monotonicity conjectures are
refuted: $c_k$ is unimodal with a unique peak $c_{13} \approx 2.1578$ and exceeds
$2$ near that peak. The proven envelope $[3/2,3)$ is thus sharp in kind.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Biased Maker--Breaker games}
In a Maker--Breaker game two players alternately claim previously unclaimed
elements of a finite ground set; Maker wins if she claims in full some element of
a fixed family of winning sets, and Breaker wins otherwise. In the biased variant
with parameter $q \ge 1$, each round Maker claims one element and Breaker claims
$q$; larger $q$ favours Breaker. We study the \emph{$C_k$-game} on $K_n$: the
ground set is $E(K_n)$ and Maker's winning sets are the edge sets of all copies of
the cycle $C_k$. Fix $k \ge 4$. There is a threshold bias, growing as a power law
in $n$, with an explicit leading constant.

\subsection{The threshold and its constant}

\begin{definition}[Threshold exponent]
For a real parameter $k$, the \emph{game exponent} is $\gm(k) = \dfrac{k-2}{k-1}$.
\end{definition}

\begin{definition}[Maximum $2$-density]
For a real parameter $k$, $m_2(k) = \dfrac{k-1}{k-2}$. For integer $k \ge 3$ this
equals the maximum $2$-density of $C_k$, attained by the full cycle.
\end{definition}

\begin{definition}[Sharp threshold constant]
For an integer $k \ge 4$,
\[
  \ck = \left[(k-1)\left(\frac{2(k-1)}{k}\right)^{k-2}\right]^{1/(k-1)}.
\]
We call $2(k-1)/k$ the \emph{average-degree factor}.
\end{definition}

\begin{definition}[Threshold bias]
For integer $k \ge 4$ and real $n > 0$, $q_k(n) = \ck \cdot n^{\gm(k)}$.
\end{definition}

Operationally, for every $\varepsilon>0$ there is $n_0$ so that for $n \ge n_0$:
Maker wins if $q < (1-\varepsilon)q_k(n)$, and Breaker wins if
$q > (1+\varepsilon)q_k(n)$. We take this location as given and analyse the
arithmetic and analytic structure of $\ck$ and $q_k(n)$.

\section{The average-degree factor}

\begin{lemma}[Lower bound]\label{lem:lb}
For every integer $k \ge 4$, $\ \dfrac{2(k-1)}{k} \ge \dfrac{3}{2}$.
\end{lemma}
\begin{proof}
As $k>0$ and $2>0$, the claim is equivalent to $4(k-1) \ge 3k$, i.e.\ $k \ge 4$.
Equality holds at $k=4$.
\end{proof}

\begin{lemma}[Upper bound]\label{lem:ub}
For every integer $k \ge 1$, $\ \dfrac{2(k-1)}{k} < 2$.
\end{lemma}
\begin{proof}
Since $k>0$, equivalent to $2(k-1) < 2k$, i.e.\ $-2<0$.
\end{proof}

\begin{lemma}[Strict monotonicity]\label{lem:mono}
$x \mapsto 2(x-1)/x$ is strictly increasing on $(0,\infty)$.
\end{lemma}
\begin{proof}
$2(x-1)/x = 2 - 2/x$; for $0<x_1<x_2$, $2/x_1 > 2/x_2$, so $2-2/x_1 < 2-2/x_2$.
\end{proof}

\section{The threshold exponent}

\begin{proposition}[Positivity]
For every real $k>2$, $\gm(k) > 0$.
\end{proposition}
\begin{proof}
Numerator $k-2>0$ and denominator $k-1>0$.
\end{proof}

\begin{proposition}[Strict upper bound]
For every real $k>1$, $\gm(k) < 1$.
\end{proposition}
\begin{proof}
As $k-1>0$, equivalent to $k-2 < k-1$, i.e.\ $-2<-1$.
\end{proof}

\begin{proposition}[Reciprocal-density identity]
$\gm(k) = 1/m_2(k)$.
\end{proposition}
\begin{proof}
$1/m_2(k) = (k-2)/(k-1) = \gm(k)$.
\end{proof}

\section{The sharp constant: identity and uniform bounds}

\begin{lemma}[Base positivity]\label{lem:base}
For every integer $k \ge 4$, $\ (k-1)\big(2(k-1)/k\big)^{k-2} > 0$.
\end{lemma}
\begin{proof}
$k-1>0$; the base $2(k-1)/k>0$, and a positive base to a natural power is
positive; a product of positives is positive.
\end{proof}

\begin{corollary}[Positivity]\label{cor:pos}
For every integer $k \ge 4$, $\ck > 0$.
\end{corollary}
\begin{proof}
A positive real power (exponent $1/(k-1)>0$) of the positive base of
Lemma~\ref{lem:base}.
\end{proof}

\begin{theorem}[Defining identity]\label{thm:id}
For every integer $k \ge 4$,
$\ \ck^{\,k-1} = (k-1)\big(2(k-1)/k\big)^{k-2}$.
\end{theorem}
\begin{proof}
With $B = (k-1)(2(k-1)/k)^{k-2} > 0$, $\ck = B^{1/(k-1)}$, so
$\ck^{k-1} = B^{(k-1)/(k-1)} = B$, using $(x^a)^b = x^{ab}$ for positive $x$ and
$\tfrac{1}{k-1}(k-1)=1$.
\end{proof}

\begin{theorem}[Uniform lower bound]\label{thm:lb}
For every integer $k \ge 4$, $\ \ck \ge \dfrac{3}{2}$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:lb}, $2(k-1)/k \ge 3/2>0$, so
$(2(k-1)/k)^{k-2} \ge (3/2)^{k-2}$. With $k-1 \ge 3$ and Theorem~\ref{thm:id},
\[
  \ck^{k-1} = (k-1)\Big(\tfrac{2(k-1)}{k}\Big)^{k-2}
  \ge (k-1)\big(\tfrac32\big)^{k-2}
  \ge 3\big(\tfrac32\big)^{k-2} \ge \big(\tfrac32\big)^{k-1}.
\]
Since $x \mapsto x^{k-1}$ is strictly increasing on $[0,\infty)$ and
$\ck,3/2 > 0$, we get $\ck \ge 3/2$.
\end{proof}

\begin{lemma}[Exponential dominance]\label{lem:exp}
For every integer $k \ge 4$, $\ (k-1)2^{\,k-2} < 3^{\,k-1}$.
\end{lemma}
\begin{proof}
Induction on $k$. Base $k=4$: $3\cdot 2^2 = 12 < 27 = 3^3$. Step: assuming
$(k-1)2^{k-2} < 3^{k-1}$,
\[
  k\cdot 2^{k-1} = 2\tfrac{k}{k-1}(k-1)2^{k-2}
  < 2\tfrac{k}{k-1}\,3^{k-1} \le 3\cdot 3^{k-1} = 3^{k},
\]
where $2k/(k-1) \le 3 \iff 3 \le k$, true for $k \ge 4$.
\end{proof}

\begin{theorem}[Uniform upper bound]\label{thm:ub}
For every integer $k \ge 4$, $\ \ck < 3$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:ub}, $0 < 2(k-1)/k < 2$, so
$(2(k-1)/k)^{k-2} < 2^{k-2}$. With $k-1>0$, Theorem~\ref{thm:id} and
Lemma~\ref{lem:exp},
\[
  \ck^{k-1} = (k-1)\Big(\tfrac{2(k-1)}{k}\Big)^{k-2}
  < (k-1)2^{k-2} < 3^{k-1}.
\]
As $x \mapsto x^{k-1}$ is strictly increasing on $[0,\infty)$ and
$\ck,3>0$, $\ck < 3$.
\end{proof}

\begin{theorem}[Uniform envelope]
For every integer $k \ge 4$, $\ \dfrac{3}{2} \le \ck < 3$.
\end{theorem}
\begin{proof}
Combine Theorems~\ref{thm:lb} and~\ref{thm:ub}.
\end{proof}

\section{Monotonicity of the bias and the sharp window}

\begin{theorem}[Strict monotonicity in board size]
Fix $k \ge 4$. Then $n \mapsto q_k(n) = \ck\, n^{\gm(k)}$ is strictly increasing
on $(0,\infty)$.
\end{theorem}
\begin{proof}
$\gm(k)>0$, so $n \mapsto n^{\gm(k)}$ is strictly increasing on $(0,\infty)$;
scaling by $\ck>0$ (Corollary~\ref{cor:pos}) preserves this.
\end{proof}

\begin{theorem}[Nonempty sharp window]
Fix $k \ge 4$, $n>0$, $\varepsilon \in (0,1)$. Then $q_k(n)>0$ and
$(1-\varepsilon)q_k(n) < q_k(n) < (1+\varepsilon)q_k(n)$, so the window
$\big((1-\varepsilon)q_k(n),(1+\varepsilon)q_k(n)\big)$ is a nonempty open
interval containing $q_k(n)$.
\end{theorem}
\begin{proof}
$q_k(n) = \ck n^{\gm(k)}$ is a product of positives, hence positive; multiply
$1-\varepsilon < 1 < 1+\varepsilon$ by $q_k(n)>0$.
\end{proof}

\section{The true shape of the constant: two refuted conjectures}

\begin{conjecture}[Monotonicity in $k$ --- \textsc{false}]
$(\ck)_{k\ge 4}$ is increasing.
\end{conjecture}
\noindent\emph{Refutation.} Evaluating
$\log \ck = \frac{\log(k-1) + (k-2)\log(2(k-1)/k)}{k-1}$ shows the sequence rises
to a unique maximum at $k=13$, $c_{13} \approx 2.1578$, then strictly decreases:
it is unimodal, not monotone.

\begin{conjecture}[Bound by $2$ --- \textsc{false}]
$\ck < 2$ for all $k$.
\end{conjecture}
\noindent\emph{Refutation.}
$c_5 = \big(4(8/5)^3\big)^{1/4} = (16.384)^{1/4} \approx 2.0119 > 2$.

These refutations sharpen the picture: the proven envelope $[3/2,3)$ is sharp in
kind, since $\sup_k \ck = c_{13} \approx 2.1578 \in [3/2,3)$, while neither $3/2$
nor $2$ bounds the sequence from above.

\section{Discussion and future work}
The constant $\ck$ is bounded in $[3/2,3)$, unimodal with peak $c_{13} \approx
2.1578$, and tends to $2$ as $k \to \infty$. Three directions follow: proving
strict unimodality via single-crossing of the derivative of $\log \ck$ in $1/k$;
establishing $\lim_k \ck = 2$ with rate $2-\ck = \Theta(\log k/k)$; and proving
joint log-concavity of $(k,n) \mapsto \log q_k(n)$, where
$\gm(k) = 1 - 1/(k-1)$ is manifestly concave in $k$.

